import{F as e,_ as t,f as n,h as r,j as i,n as a}from"./chunks/shared.rYHlazZf.js";var o=JSON.parse(`{"title":"复用与审查运行时变量","description":"","frontmatter":{"title":"复用与审查运行时变量","docId":"user.automations.variables","translationKey":"user.automations.variables","locale":"zh","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"afcdc4049fccbd2bc17c1040a9f84efb749a8d6291212cfe8809c22728e5c0fb","translationRevision":"f69aaeef5f6fa10bf2255eb8acaf8bec74a662aca482790e3a6f8c2bbf09fa59","order":40},"headers":[],"relativePath":"zh/user/automations/variables.md","filePath":"zh/user/automations/variables.md","lastUpdated":1795731074000}`),s={name:`zh/user/automations/variables.md`};function c(a,o,s,c,l,u){let d=e(`DemoFrame`);return i(),n(`div`,null,[o[0]||=r(`<h1 id="reuse-and-review-runtime-variables" tabindex="-1">复用与审查运行时变量 <a class="header-anchor" href="#reuse-and-review-runtime-variables" aria-label="Permalink to “复用与审查运行时变量”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目标与前置条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “目标与前置条件”">​</a></h2><p>只修改一次共用值，就能在多个操作中复用。你需要 <strong>自动化 → 变量</strong>，以及支持相关变量操作的宿主。类型化编辑与经过审查的 Cloud 操作会按宿主能力显示；本地保存无需上传。</p><h2 id="save-a-local-value" tabindex="-1">保存本地值 <a class="header-anchor" href="#save-a-local-value" aria-label="Permalink to “保存本地值”">​</a></h2><ol><li>添加名为 <code>showLabel</code> 的变量。键以字母或下划线开头，可包含字母、数字、点、下划线和连字符，最多 <code>64</code> 个字符。避免重复键。</li><li>支持类型化编辑时，选择文本并输入 <code>晚间直播</code>。其他支持的类型包括数字、布尔值、列表和秘密值。列表使用字符串 JSON 数组，例如 <code>[&quot;红色&quot;, &quot;蓝色&quot;]</code>。</li><li>选择 <strong>保存全局变量</strong>。修订冲突说明已保存的集合发生变化；请重新加载，并据此审查要进行的编辑。</li><li>在支持模板的操作字段中使用保存的值：</li></ol><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{{ globals.showLabel }}：{{ event.user.uniqueId }}</span></span></code></pre></div><ol start="5"><li>测试一个仅写日志的操作，查看渲染文本。修改 <code>showLabel</code>、再次保存，再运行新测试。现有操作定义可复用更新值，无需重新导入模板。</li></ol><p>模板的 <code>params</code> 在应用模板时替换；<code>globals</code> 则在执行时读取。缺失的运行时键会渲染为空文本，因此用作目标或标识符前，请验证拼写。使用字段的变量建议，选择适合其触发器的事件路径。</p><p>条件还可以按匹配发布值。当过滤器声明捕获别名时，满足它的值会在该事件的操作渲染期间以 <code>{{ match.&lt;alias&gt; }}</code>（无别名时为 <code>{{ match.&lt;位置&gt; }}</code>）的形式可用。例如，对评论使用别名为 <code>prefix</code> 的“开头为”条件，可以让日志操作输出 <code>{{ match.prefix }}</code>。捕获是有上限的纯文本，仅由实际匹配的过滤器和备选生成，且不会改变冷却键。</p><p>点击模板字段旁的 <strong>+</strong> 可打开 <strong>插入变量</strong>：右侧显示精确路径，选择一行会把 <code>{{ 路径 }}</code> 追加到字段中。此事件的捕获值也在列表中，但只有在对应条件实际匹配时才会解析。要使用 <code>{{ match.&lt;alias&gt; }}</code>，请在“条件”区域设置别名（底部 <strong>捕获</strong> 按钮可显示别名字段）；否则使用位置形式 <code>{{ match.&lt;位置&gt; }}</code>。</p><h2 id="review-cloud-changes-separately" tabindex="-1">单独审查 Cloud 变更 <a class="header-anchor" href="#review-cloud-changes-separately" aria-label="Permalink to “单独审查 Cloud 变更”">​</a></h2><p>宿主支持时，变量的 <strong>更改</strong> 控件提供经过审查的原生发送、获取、应用/采纳及撤回操作。先保存本地编辑，再选择比较项、检查其类型和值，并明确选择所需方向。获取 Cloud 候选项与将它应用到本地是两个步骤；撤回共享值也不同于删除本地行。</p><p>秘密值或被阻止的值在比较中会被遮蔽，且不能通过此审查路径发送。不要为了绕过限制而将秘密值改成普通文本。</p><h2 id="expected-result-status-and-recovery" tabindex="-1">预期结果、状态与恢复 <a class="header-anchor" href="#expected-result-status-and-recovery" aria-label="Permalink to “预期结果、状态与恢复”">​</a></h2><p>本地变量及按能力启用的审查式共享均可使用；本地保存从不自动上传。无效键、无效类型值和过期修订会阻止保存。重试前，请修正高亮字段或重新加载。账户故障见 <a href="./../cloud/account.html">Cloud 账户</a>，比较行为见<a href="./../cloud/changes.html">变更</a>。</p><p>在改动真实配置之前先交互式试用:</p>`,16),t(d,{scenario:`automation`,locale:`zh`,panel:`automation`,title:`试用自动化工作区`}),o[1]||=r(`<h2 id="command-line-operations" tabindex="-1">命令行操作 <a class="header-anchor" href="#command-line-operations" aria-label="Permalink to “命令行操作”">​</a></h2><p>本指南中的每个操作也可通过 CLI 使用——离线、可编写脚本、适合代理。用法行是解析器语法,在所有语言中保持英文。</p><table tabindex="0"><thead><tr><th>命令</th><th>摘要</th></tr></thead><tbody><tr><td><code>tiktools globals list</code></td><td>列出所有全局键</td></tr><tr><td><code>tiktools globals get &lt;key&gt;</code></td><td>读取一个全局变量</td></tr><tr><td><code>tiktools globals set &lt;key&gt; &lt;value&gt;</code></td><td>写入一个全局变量</td></tr><tr><td><code>tiktools globals delete &lt;key&gt;</code></td><td>删除一个全局变量 <strong>破坏性</strong></td></tr></tbody></table><p>查看<a href="./../../developer/cli.html">完整命令参考</a>了解约定、JSON 输出和破坏性操作标记。</p>`,4)])}var l=a(s,[[`render`,c]]);export{o as __pageData,l as default};